export type PlatformTabId = "core" | "architecture" | "performance" | "types";
export interface PlatformFeature { readonly title: string; readonly desc: string; }
type ThreeFeatures = readonly [PlatformFeature, PlatformFeature, PlatformFeature];
export interface PlatformTabContent { readonly id: PlatformTabId; readonly label: string; readonly titlePre: string; readonly highlight: string; readonly intro: string; readonly imageAlt: string; readonly features: ThreeFeatures; }
export interface PlatformOverviewContent { readonly titleLead: string; readonly titleAccent: string; readonly intro: string; readonly tabs: readonly [PlatformTabContent, PlatformTabContent, PlatformTabContent, PlatformTabContent]; }
type FeaturePairs = readonly [readonly [string, string], readonly [string, string], readonly [string, string]];
type PanelDraft = readonly [string, string, string, string, string, FeaturePairs];
function platform(titleLead: string, intro: string, panels: readonly [PanelDraft, PanelDraft, PanelDraft, PanelDraft]): PlatformOverviewContent {
  const tab = (id: PlatformTabId, p: PanelDraft): PlatformTabContent => { const f = (x: readonly [string,string]): PlatformFeature => ({ title:x[0],desc:x[1] }); return { id,label:p[0],titlePre:p[1],highlight:p[2],intro:p[3],imageAlt:p[4],features:[f(p[5][0]),f(p[5][1]),f(p[5][2])] }; };
  return { titleLead,titleAccent:"Overview",intro,tabs:[tab("core",panels[0]),tab("architecture",panels[1]),tab("performance",panels[2]),tab("types",panels[3])] };
}

