function normalizePath(path: string | null | undefined): string { if (!path) return "/"; const clean=path.trim().split(/[?#]/,1)[0].toLowerCase(); return clean&&clean!=="/"?`/${clean.replace(/^\/+|\/+$/g,"")}/`:"/"; }
export function getPlatformOverviewContent(path: string | null | undefined): PlatformOverviewContent { return platformOverviewContent[normalizePath(path)] || platformOverviewContent["/services/database-development/"]; }
export function getContextStudyContent(path: string | null | undefined): ContextStudyContent { return contextStudyContent[normalizePath(path)] || contextStudyContent["/services/data-analytics/"]; }
